$text = [System.IO.File]::ReadAllText($filePath)
$lines = $text -split "`n" | Where-Object { $_ -ne "" -or $lines.IndexOf($_) -eq ($lines.Count - 1) }

Write-Host "=== VERIFICATION RESULTS ===" -ForegroundColor Cyan

# 1. Line count
$lineCount = ($text -split "`n").Count
if ($text.EndsWith("`n")) {
    $lineCount--
}
Write-Host "Line count: $lineCount (expected: 12)" -ForegroundColor $(if ($lineCount -eq 12) { "Green" } else { "Red" })

# 2. Each line length
$fileLines = $text -split "`n" | Select-Object -SkipLast 1
Write-Host "Line lengths:" -ForegroundColor Cyan
$allLengthsOk = $true
$fileLines | ForEach-Object {
    $len = $_.Length
    $status = if ($len -ge 20 -and $len -le 48) { "OK" } else { "FAIL" }
    $statusColor = if ($len -ge 20 -and $len -le 48) { "Green" } else { "Red" }
    Write-Host "  Length $len ($status)" -ForegroundColor $statusColor
    if ($len -lt 20 -or $len -gt 48) { $allLengthsOk = $false }
}

# 3. No trailing whitespace
Write-Host "Trailing whitespace check:" -ForegroundColor Cyan
$hasTrailing = $false
$fileLines | ForEach-Object {
    if ($_ -match '\s$') {
        Write-Host "  Line has trailing whitespace: '$_'" -ForegroundColor Red
        $hasTrailing = $true
    }
}
if (-not $hasTrailing) {
    Write-Host "  No trailing whitespace found" -ForegroundColor Green
}

# 4. Allowed characters only
Write-Host "Character validation:" -ForegroundColor Cyan
$allowedChars = [char[]]"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 +-|/\\_*.#():=-"
$invalidChars = @()
$fileLines | ForEach-Object {
    $line = $_
    $line.ToCharArray() | ForEach-Object {
        if ($allowedChars -notcontains $_) {
            if ($invalidChars -notcontains $_) {
                $invalidChars += $_
            }
        }
    }
}
if ($invalidChars.Count -eq 0) {
    Write-Host "  Only allowed characters found" -ForegroundColor Green
} else {
    Write-Host "  Invalid characters found: $($invalidChars -join ', ')" -ForegroundColor Red
}

# 5. Contains CONFIG
Write-Host "CONFIG substring check:" -ForegroundColor Cyan
$hasConfig = $text -match "CONFIG"
Write-Host "  Contains 'CONFIG': $(if ($hasConfig) { 'Yes' } else { 'No' })" -ForegroundColor $(if ($hasConfig) { "Green" } else { "Red" })

# 6. Ends with single newline
Write-Host "Line ending check:" -ForegroundColor Cyan
$endsWithLF = $rawContent[-1] -eq 10
$endsWithCRLF = $rawContent.Length -ge 2 -and $rawContent[-2] -eq 13 -and $rawContent[-1] -eq 10
