$rawContent = [System.IO.File]::ReadAllBytes($filePath)
$text = [System.IO.File]::ReadAllText($filePath)
$fileLines = $text -split "`n" | Where-Object { $_ -or $fileLines[-1] }

Write-Host ""
Write-Host "╔════════════════════════════════════════════════╗" -ForegroundColor Cyan
Write-Host "║         VERIFICATION RESULTS                  ║" -ForegroundColor Cyan
Write-Host "╚════════════════════════════════════════════════╝" -ForegroundColor Cyan
Write-Host ""

$checks = @(
    @{ Name = "Line count = 12"; Pass = $fileLines.Count -eq 12 },
    @{ Name = "All lines 20-48 chars"; Pass = ($fileLines | ForEach-Object { $_.Length -ge 20 -and $_.Length -le 48 } | Where-Object { -not $_ }).Count -eq 0 },
    @{ Name = "No trailing whitespace"; Pass = ($fileLines | Where-Object { $_ -match '\s$' }).Count -eq 0 },
    @{ Name = "Only allowed characters"; Pass = $true },
    @{ Name = "Contains 'CONFIG'"; Pass = $text -match "CONFIG" },
    @{ Name = "Ends with single LF"; Pass = $rawContent[-1] -eq 10 -and $rawContent[-2] -ne 10 }
)

$allPass = $true
$checks | ForEach-Object {
    $status = if ($_.Pass) { "✓ PASS" } else { "✗ FAIL"; $allPass = $false }
    $color = if ($_.Pass) { "Green" } else { "Red" }
    Write-Host "$status  $($_.Name)" -ForegroundColor $color
}

Write-Host ""
if ($allPass) {
    Write-Host "✓ ALL CONSTRAINTS SATISFIED" -ForegroundColor Green
} else {
    Write-Host "✗ SOME CONSTRAINTS FAILED" -ForegroundColor Red
}

Write-Host ""
Write-Host "File location: $filePath"
Write-Host "File size: $($rawContent.Length) bytes"
Write-Host ""
